import{_ as o,c as d,o as r,a2 as n}from"./chunks/framework.CHomSxuB.js";const q=JSON.parse('{"title":"1 · V5 信号体系与考决","description":"","frontmatter":{},"headers":[],"relativePath":"足球信号雷达/1-V5信号体系与考决.md","filePath":"足球信号雷达/1-V5信号体系与考决.md"}'),s={name:"足球信号雷达/1-V5信号体系与考决.md"};function g(e,t,a,p,h,u){return r(),d("div",null,t[0]||(t[0]=[n('<h1 id="_1-·-v5-信号体系与考决" tabindex="-1">1 · V5 信号体系与考决 <a class="header-anchor" href="#_1-·-v5-信号体系与考决" aria-label="Permalink to &quot;1 · V5 信号体系与考决&quot;">​</a></h1><blockquote><p>状态：<strong>V5 四信号冻结后 OOS 观测中（截至 2026-09-20）</strong> 口径：命中 = 不败方向命中；超额 = 命中率 − 赔率隐含概率（去水）</p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p><hr><h2 id="一、v5-是什么" tabindex="-1">一、V5 是什么 <a class="header-anchor" href="#一、v5-是什么" aria-label="Permalink to &quot;一、V5 是什么&quot;">​</a></h2><p>老一代&quot;裁判层&quot;（多路亚盘/大小球/欧赔信号汇总成单一裁定）在真实回放中被证伪为负期望后（见 <a href="./2-历史战线与下注层废弃.html">2-历史战线与下注层废弃</a>）， 项目 2026-08 重建为 <strong>V5：只保留&quot;方向级&quot;欧赔信号</strong>——不预测比分、不猜庄家意图，只回答一个问题： <strong>这个市场的钱在往哪边走，跟不跟。</strong></p><p>V5 的信号全部是<strong>结构规则</strong>（由赔率轨迹的形态触发），不是机器学习——定稿后禁止在同一段历史上再挖阈值，防过拟合。</p><h2 id="二、2026-08-21-冻结考决-5-规则-→-4-活-1-死" tabindex="-1">二、2026-08-21 冻结考决：5 规则 → 4 活 1 死 <a class="header-anchor" href="#二、2026-08-21-冻结考决-5-规则-→-4-活-1-死" aria-label="Permalink to &quot;二、2026-08-21 冻结考决：5 规则 → 4 活 1 死&quot;">​</a></h2><p>一周样本外（OOS）考决后，信号体系定稿。判决表（考决段 OOS 实测）：</p><table tabindex="0"><thead><tr><th>信号</th><th>语义（脱敏）</th><th>OOS 命中 (n)</th><th>超额</th><th>EV/注</th><th>判决</th></tr></thead><tbody><tr><td><strong>SSS_VETO_H</strong></td><td>定盘星背离：强热门区里大众盘压主、职业盘反向抬主 → 跟职业防守方向（客不败）</td><td>86.7% (15 场)</td><td>+40.0pp</td><td>+93.7%</td><td>✅ 存活（样本偏小）</td></tr><tr><td><strong>SSS_GLOBAL_DRIFT</strong></td><td>弱势弃守（客向）：主队弱势 + 主胜赔率被市场持续抬升 → 客不败</td><td>76.6% (171 场)</td><td>+22.0pp</td><td>+35.0%</td><td>✅ 存活</td></tr><tr><td><strong>SSS_HOME_DRIFT</strong></td><td>弱势弃守（主向）：客队弱势 + 客胜赔率被市场持续抬升 → 主不败</td><td>73.6% (246 场)</td><td>+20.5pp</td><td>+32.1%</td><td>✅ 存活</td></tr><tr><td><strong>A_UNDERDOG_QUAKE</strong></td><td>准冷门震荡：弱势方赔率大幅下滑（资金涌入）→ 弱队不败倾向</td><td>61.3% (80 场)</td><td>+28.2pp</td><td>+70.3%</td><td>✅ 存活</td></tr><tr><td>A_DRAW_MAGNET</td><td>低平赔·平局引力</td><td>35.7% (28 场)</td><td>+3.7pp</td><td>+1.5%</td><td>❌ 淘汰（无 edge）</td></tr></tbody></table><p>考决中同步处死的两个&quot;虚高信号&quot;——<strong>这是本系列最有价值的部分</strong>：</p><ol><li><strong>赔率版定盘星（SSS_VETO 原版）</strong>：样本段 82% 命中 → OOS 掉到 54.5%（−27.5pp，EV −7.1%）。 典型的多重检验虚高：在历史里&quot;试&quot;出来的好规则，一到样本外就打回原形。其 <code>Δlog + 强热门区</code> 变体（即上面存活的 VETO_H）被救活。</li><li><strong>升级逻辑（概率流向 → 直接看主胜/客胜）</strong>：比赔率版低 6~7pp，且 OOS 分歧场次对旧版全错——<strong>确认负贡献，禁用</strong>。</li></ol><h2 id="三、冻结纪律" tabindex="-1">三、冻结纪律 <a class="header-anchor" href="#三、冻结纪律" aria-label="Permalink to &quot;三、冻结纪律&quot;">​</a></h2><ul><li>上述 4 条定稿后<strong>不再修改、不再挖阈值</strong>（同段挖参 = 自欺）；</li><li>判据线：<strong>SSS_VETO 需累计 50+ 场且命中率 &gt;70% 才谈转正</strong>；QUAKE 的两家版 vs 赔率版之争交给样本说话；</li><li>真实生产 edge 应低于考决数字（考决用最终态赔率快照，与赛前实时信号存在时点漂移——08-18 实测同一场赛前/赛后重跑信号会变）。</li></ul><h2 id="四、当前-oos-状态-每日对账-滚动窗口自-2026-08-15-起" tabindex="-1">四、当前 OOS 状态（每日对账，滚动窗口自 2026-08-15 起） <a class="header-anchor" href="#四、当前-oos-状态-每日对账-滚动窗口自-2026-08-15-起" aria-label="Permalink to &quot;四、当前 OOS 状态（每日对账，滚动窗口自 2026-08-15 起）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>n</th><th>命中</th><th>赔率隐含</th><th>超额</th><th>判据进度</th></tr></thead><tbody><tr><td>SSS_HOME_DRIFT</td><td>1315</td><td>82.4%</td><td>78.7%</td><td><strong>+3.7pp</strong></td><td>⚠️ 观察</td></tr><tr><td>SSS_GLOBAL_DRIFT</td><td>888</td><td>78.4%</td><td>76.3%</td><td><strong>+2.0pp</strong></td><td>⚠️ 观察（超额自 +1.1pp 回升至 +2.0pp）</td></tr><tr><td>SSS_VETO（定盘星背离族）</td><td>63</td><td>88.9%</td><td>75.5%</td><td><strong>+13.4pp</strong></td><td>✅ 已达 50 场判据线（63 场 / 88.9% &gt; 70%）；<strong>超额自到线后回落，近 4 日零新增</strong></td></tr><tr><td>A_UNDERDOG_QUAKE</td><td>27</td><td>59.3%</td><td>61.6%</td><td><strong>−2.3pp</strong></td><td>⏳ 27/50（<strong>超额转负</strong>）</td></tr></tbody></table><p><strong>影子轨（符号修正对照 · 纯观测）</strong>：</p><table tabindex="0"><thead><tr><th>信号</th><th>n</th><th>命中率</th><th>超额</th><th>判据进度</th></tr></thead><tbody><tr><td>SSS_VETO_H_FIX（2026-09-07 建轨）</td><td>46</td><td>93.5%</td><td><strong>+12.3pp</strong></td><td>⏳ 46/50（n≥50 前仅记账不裁决）</td></tr></tbody></table><p>样本变化趋势（自 08-21 冻结以来）：HOME 246→1315、GLOBAL 171→888、VETO 15→63、QUAKE 80→27（注：QUAKE 是滚动窗口重切后重新累计，n 回落属正常）。</p><p><strong>读数方式</strong>（重要，避免误读）：</p><ul><li>两条 DRIFT（1315/888 场）已是全场最大样本，超额收窄到 <strong>+3.7 / +2.0pp</strong>——<strong>&quot;样本变大、虚高退潮&quot;的迹象</strong>： 考决时的 +20pp 级超额大部分是回测乐观偏差，真实结构优势比想象的小，但方向仍为正；按脚本判据口径 （n≥50 且超额 &gt;5pp 才升&quot;转正候选&quot;），两者均未达；</li><li><strong>VETO 的&quot;到线后退潮&quot;值得单独记一笔</strong>：09-13 到线时为 56 场 / 91.1% / <strong>+16.1pp</strong>， 此后样本增至 63 场、命中率降至 88.9%、超额降至 <strong>+13.4pp</strong>（近 4 个统计日零新增）。 即&quot;到线&quot;不是终点——<strong>它的数字同样在朝均值回归</strong>，与两条 DRIFT 的规律一致。 但&quot;到线&quot;只等于<strong>具备谈转正的资格</strong>，不等于转正——转正是规则/定位层面的变更，须用户裁决并留预注册卷宗； 且考决文档自己警告过它&quot;考决段仅 15 场&quot;，样本虽到线、置信区间仍宽，<strong>到线前不作结论、到线后也不自动转正</strong>；</li><li><strong>QUAKE 超额转负</strong>（27 场 / 59.3% / <strong>−2.3pp</strong>）：样本仍不足 50，只描述不裁决； 但要如实记下——它在 09-13 时还是 +6.6pp，之后随样本增加一路回落到负区间，是&quot;虚高退潮&quot;最剧烈的一条。 超额为负意味着<strong>信号命中率已低于市场自身隐含概率</strong>，这是需要警惕的方向。</li></ul><h2 id="五、veto-h-的符号核实-一次-修-bug-会杀掉真-edge-的复盘-2026-09-07" tabindex="-1">五、VETO_H 的符号核实：一次&quot;修 bug 会杀掉真 edge&quot;的复盘（2026-09-07） <a class="header-anchor" href="#五、veto-h-的符号核实-一次-修-bug-会杀掉真-edge-的复盘-2026-09-07" aria-label="Permalink to &quot;五、VETO_H 的符号核实：一次&quot;修 bug 会杀掉真 edge&quot;的复盘（2026-09-07）&quot;">​</a></h2><p>一次外部代码审查指出：定盘星背离（VETO_H）的赔率位移计算里，<strong>传入的是去水后的概率而非原始赔率</strong>， 导致实际触发语义与文档宣称<strong>方向相反</strong>。核实结论如下（脱敏，仅列方法）：</p><ol><li><p><strong>Bug 属实</strong>：位移函数喂错了输入（该用原始赔率处用了去水概率），使实际计算量变成&quot;概率的对数位移&quot;； 因去水归一化会引入符号反转，<strong>实际 firing 语义 = 两家职业盘大位移背离下的&quot;锐钱回热&quot;</strong>， 与注释宣称的&quot;锐钱离场&quot;方向相反。</p></li><li><p><strong>但&quot;修复&quot;会杀掉唯一真 edge</strong>：按注释原意做对照回测（口径对齐 OOS），</p><table tabindex="0"><thead><tr><th>版本</th><th>n</th><th>命中率</th><th>超额</th></tr></thead><tbody><tr><td>现役版（实际计算）</td><td>52</td><td>90.4%</td><td><strong>+15.8pp</strong></td></tr><tr><td>文字原意版（&quot;修 bug&quot;后）</td><td>48</td><td>91.7%</td><td><strong>+9.2pp</strong></td></tr></tbody></table><p><strong>两版触发集完全不相交</strong>（数学必然：同一腿的 logP 降 ⟺ logOdds 升），且<strong>两个相反方向各自为正超额</strong>。</p></li><li><p><strong>处置（三条，均不改判定口径）</strong>：</p><ul><li>文档带日期<strong>勘误</strong>（不静默改写历史），并把&quot;禁止盲目修参&quot;写成代码注释；</li><li>摘除已处死的<strong>展示层方向标签</strong>（升级逻辑早在 08-21 考决被判负贡献，纯显示层，不进入统计）；</li><li>建<strong>独立影子轨</strong>并行取证——&quot;文字原意版&quot;作为对照信号持续记账，n≥50 前不参与任何裁决。</li></ul></li></ol><blockquote><p><strong>这条的价值不在&quot;抓到一个 bug&quot;，而在暴露了一种更危险的冲动：看到实现与注释不符就条件反射地&quot;修&quot;。</strong> 当实测 edge 归属于带 Bug 的实际计算时，Bug 是<strong>承重的</strong>——修掉它等于换了一个从未验证过的方向。 真正的判别特征也许根本不是&quot;方向&quot;，而是&quot;<strong>两家职业盘大位移背离 + 热门区错位定价</strong>&quot;这一类结构， 方向只是它的两个切面。edge 归属必须由数据裁决，不能由故事裁决。</p></blockquote><h2 id="六、候选过滤规则-未转正-观察中" tabindex="-1">六、候选过滤规则（未转正，观察中） <a class="header-anchor" href="#六、候选过滤规则-未转正-观察中" aria-label="Permalink to &quot;六、候选过滤规则（未转正，观察中）&quot;">​</a></h2><p>欧亚同向性观测（&quot;亚盘让球方 = 欧赔信号受益方&quot;为同向）：</p><table tabindex="0"><thead><tr><th>口径</th><th>同向</th><th>反向（冲突）</th><th>差值</th></tr></thead><tbody><tr><td>回测验证</td><td>83.0%</td><td>62.3%</td><td>+20.7pp</td></tr><tr><td>OOS 跟踪（截至 09-20）</td><td>83.5%（1978 场）</td><td>63.5%（315 场）</td><td>+20.0pp</td></tr></tbody></table><p>OOS 与回测基本一致（差值稳定在 +20pp 附近）——若维持，则&quot;欧亚方向冲突的场次信号不可信&quot;可成候选过滤规则。 <strong>当前仅为观测，未改任何信号规则。</strong></p><hr><blockquote><p>结论（截至 2026-09-20）：V5 四信号<strong>无一判死</strong>，但内部分化明显—— 两条 DRIFT 超额稳在 <strong>+3.7 / +2.0pp</strong>（低于 &gt;5pp 转正门槛）；VETO 走完 50 场判据线后 <strong>数字开始向均值回归</strong>（56→63 场，91.1%→88.9%，+16.1→+13.4pp）；QUAKE <strong>超额转负</strong>（27 场 / −2.3pp）。 一句话：<strong>没有一条线在&quot;到线之后变得更好&quot;</strong>——这恰好印证了本项目&quot;样本变大、虚高退潮&quot;的核心预期。 VETO 是否转正须用户裁决并留预注册卷宗。<strong>全部信号仍在观察期，无一转正。</strong></p></blockquote><p><a href="/足球信号雷达/">返回 足球信号雷达 首页</a></p>',32)]))}const i=o(s,[["render",g]]);export{q as __pageData,i as default};
